package com.jnapanam.sportszone.tournament.controller;import com.jnapanam.sportszone.tournament.dto.*;import com.jnapanam.sportszone.tournament.service.TournamentService;import java.util.*;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/v1/public/tournaments")public class PublicTournamentController{private final TournamentService service;public PublicTournamentController(TournamentService s){service=s;}@GetMapping public List<TournamentResponse>list(){return service.publicList();}@GetMapping("/{id}/fixtures")public List<FixtureResponse>fixtures(@PathVariable UUID id){return service.fixtureList(id);}}
